@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix ns2: <http://www.w3.org/2003/06/sw-vocab-status/ns#> .
@prefix ns3: <http://www.cidoc-crm.org/cidoc-crm/> .
@prefix schema: <https://schema.org/> .
@prefix odrl: <http://www.w3.org/ns/odrl/2/> .

<http://example.org/Letter1> rdf:type ns2:CACAO_0000080 ;
    rdf:type ns3:E33_Linguistic_Object ;
    rdf:type schema:TextObject ;
    ns3:P3_has_note "A four-page letter" ;
    ns3:P129_is_about <http://example.org/CongressWork> ;
    ns3:P129_is_about <http://example.org/ElectionVikelas> ;
    ns3:P129_is_about <http://example.org/OlympicGamesRevivalCommittee> ;
    ns3:P129_is_about <http://example.org/ProposedAthens> .

<http://example.org/Vikelas> rdf:type ns3:E21_Person ;
    rdf:type odrl:Party ;
    ns3:P1_is_identified_by <http://example.org/VikelasName> .

<http://example.org/VikelasName> rdf:type ns3:E41_Appellation ;
    rdfs:label "D. Vikelas" .

<http://example.org/Fokianos> rdf:type ns3:E21_Person ;
    rdf:type odrl:Party ;
    ns3:P1_is_identified_by <http://example.org/FokianosName> .

<http://example.org/FokianosName> rdf:type ns3:E41_Appellation ;
    rdfs:label "Ioannis Fokianos" .

<http://example.org/CongressWork> rdf:type ns3:E5_Event ;
    ns3:P3_has_note "informing him of the work of the Congress" .

<http://example.org/ElectionVikelas> rdf:type ns3:E5_Event ;
    ns3:P3_has_note "announcing his election as President" .

<http://example.org/OlympicGamesRevivalCommittee> rdf:type ns3:E74_Group ;
    ns3:P3_has_note "committee in charge of the revival of the Olympic Games" .

<http://example.org/ProposedAthens> rdf:type ns3:E5_Event ;
    ns3:P3_has_note "informing him of his intention to propose ATHENS for the holding of the First International Olympic Games" .

<http://example.org/Letter1> odrl:hasConstraint [
    odrl:leftOperand "date" ;
    odrl:operator "eq" ;
    odrl:rightOperand "18-6-1894"^^xsd:date
] .
